case class Evacuation(initialState: EvaFloorMap, states: List[EvaFloorMap], steps: List[Int]) {

  def stepNr(stateNr: Int): Int =
    steps.count(_ <= stateNr)

  def nextMicroStep(curStep: Int): Int = {
    if (curStep >= states.size - 1) states.size - 1
    else if (curStep < 0) 0
    else curStep + 1
  }

  def previousMicroStep(curStep: Int): Int = {
    if (curStep >= states.size) states.size - 1
    else if (curStep < 1) 0
    else curStep - 1
  }

  def nextStep(curStep: Int): Int = {
    steps.filter(_ > curStep).minOption.getOrElse(states.size - 1)
  }

  def stepBeginOfState(curState: Int): Int = {
    if (steps.contains(curState)) {
      curState
    } else {
      previousStep(curState)
    }
  }

  def previousStep(curStep: Int): Int = {
    steps.filter(_ < curStep).maxOption.getOrElse(0)
  }

  def getStepsAsList(): List[EvaFloorMap] =
    steps.map(states(_))

  def tracePerson(id: Integer): List[PositionInMatrix] = getStepsAsList().flatMap(_.getPositionOfPerson(id))

  def getNextDirectionOfPerson(currentState: Integer, id: Integer): Option[Direction] = {

    val curPos = states(currentState).getPositionOfPerson(id)

    var nextState = nextStep(currentState)
    var nextPos = states(nextState).getPositionOfPerson(id)

    while (nextPos.nonEmpty && curPos == nextPos && nextState != states.length - 1) {
      nextState = nextStep(nextState)
      nextPos = states(nextState).getPositionOfPerson(id)
    }

    if (curPos.isDefined && nextPos.isDefined) Direction.fromPosition(nextPos.get.cPos.sub(curPos.get))
    else None


  }
}

